import{_ as a}from"./chunks/xiaozhi.BzgqTxQ2.js";import{_ as r}from"./chunks/dashboard.zh.BjnfxaX4.js";import{_ as e,c as o,o as d,ae as i}from"./chunks/framework.BnYZi0O_.js";const g=JSON.parse('{"title":"小智接入","description":"","frontmatter":{},"headers":[],"relativePath":"configuration/xiaozhi.md","filePath":"configuration/xiaozhi.md"}'),l={name:"configuration/xiaozhi.md"};function n(h,t,s,c,b,p){return d(),o("div",null,t[0]||(t[0]=[i('<h1 id="小智接入" tabindex="-1">小智接入 <a class="header-anchor" href="#小智接入" aria-label="Permalink to &quot;小智接入&quot;">​</a></h1><p>xiaozhi-mcphub 通过 <strong>WebSocket 多端点</strong> 与小智 AI 平台对接：每个登录用户管理自己的端点列表，可绑定分组或启用智能路由。</p><p><img src="'+a+'" alt="小智端点页"></p><h2 id="前置条件" tabindex="-1">前置条件 <a class="header-anchor" href="#前置条件" aria-label="Permalink to &quot;前置条件&quot;">​</a></h2><ul><li>配置 <strong><code>DB_URL</code></strong>（小智端点持久化依赖数据库）</li><li>控制台已登录</li><li>小智侧提供可连的 <code>wss://...</code> 地址（含 token 等查询参数时，界面会脱敏展示）</li></ul><h2 id="在控制台操作" tabindex="-1">在控制台操作 <a class="header-anchor" href="#在控制台操作" aria-label="Permalink to &quot;在控制台操作&quot;">​</a></h2><ol><li>侧栏进入 <strong>小智</strong></li><li><strong>添加端点</strong>：名称、WebSocket URL、是否启用、分组 / 智能路由、重连参数</li><li>可对单个端点：启用/禁用、编辑、重连、删除</li><li>顶部状态（服务状态、总端点数、已启用、已连接）由<strong>当前用户可见端点</strong>聚合，<strong>不再</strong>使用全局「总开关」切断连接</li></ol><p>管理员可看到全部端点；普通用户仅自己的。无 owner 的遗留端点视为管理员资源。</p><h2 id="配置字段-概念" tabindex="-1">配置字段（概念） <a class="header-anchor" href="#配置字段-概念" aria-label="Permalink to &quot;配置字段（概念）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td>名称</td><td>展示名</td></tr><tr><td>WebSocket URL</td><td>小智下发的接入地址</td></tr><tr><td>启用</td><td>是否参与连接</td></tr><tr><td>分组</td><td>可选，限制工具集；或「无分组」</td></tr><tr><td>智能路由</td><td>使用 <code>$smart</code> 语义检索工具</td></tr><tr><td>重连</td><td>初始延迟、最大次数、最大延迟、退避倍数等</td></tr></tbody></table><p>也可用环境变量调节<strong>进程级</strong>重连行为（见 <a href="/xiaozhi-mcphub/configuration/environment-variables.html">环境变量</a> 小智一节）。</p><h2 id="与-mcp-工具同步" tabindex="-1">与 MCP 工具同步 <a class="header-anchor" href="#与-mcp-工具同步" aria-label="Permalink to &quot;与 MCP 工具同步&quot;">​</a></h2><p>当 MCP 服务器工具列表变化时，服务会通知已连接的小智端点，保持工具清单大致同步（视连接状态与实现而定）。</p><h2 id="仪表盘" tabindex="-1">仪表盘 <a class="header-anchor" href="#仪表盘" aria-label="Permalink to &quot;仪表盘&quot;">​</a></h2><p>主仪表盘也会展示小智相关摘要（服务是否有启用端点、端点数量、连接数等），并与服务器列表、MCP 接入 URL 同页展示。</p><p><img src="'+r+'" alt="仪表盘含小智摘要"></p><h2 id="兼容说明-1-1-0" tabindex="-1">兼容说明（1.1.0） <a class="header-anchor" href="#兼容说明-1-1-0" aria-label="Permalink to &quot;兼容说明（1.1.0）&quot;">​</a></h2><ul><li>旧版「实例级 enabled 总开关」<strong>不再作为连接门闸</strong>；<code>updateXiaozhiConfig</code> 类接口会批量切换<strong>当前用户</strong>端点</li><li>管理员仍可能看到诊断用的 legacy 全局标记，但不控制连接</li><li>API 返回的 <code>enabled</code> 对用户表示「其名下是否有启用中的端点」</li></ul><h2 id="故障排除" tabindex="-1">故障排除 <a class="header-anchor" href="#故障排除" aria-label="Permalink to &quot;故障排除&quot;">​</a></h2><table tabindex="0"><thead><tr><th>现象</th><th>建议</th></tr></thead><tbody><tr><td>页面报错 / 空列表</td><td>检查 <code>DB_URL</code>、迁移是否成功</td></tr><tr><td>一直断开</td><td>检查 URL/token、网络、重连参数；看后端日志</td></tr><tr><td>工具不全</td><td>确认绑定分组是否过窄；服务器是否在线；是否应开智能路由</td></tr><tr><td>非管理员看不见某端点</td><td>是否 owner 不匹配（隔离预期行为）</td></tr></tbody></table>',20)]))}const f=e(l,[["render",n]]);export{g as __pageData,f as default};
